const M = (...a) => a;
export const MIS = [
  M('COMPOST_MATERIALS', 'M_AG4_CM_ANY', 'Thinks any waste can go on the compost heap (polythene, tins, glass).', 'Which of these should NOT go on a compost heap?', 'A polythene bag', 'Banana peelings', 'The child thinks a compost heap is a general rubbish heap.', 'Dig up an old heap with a teacher. Ask what rotted and what did not.', 'Polythene, tins and glass do not rot and spoil the manure. Only things that were once plants, and animal dung, go on the heap.'),
  M('COMPOST_MATERIALS', 'M_AG4_CM_MEAT', 'Thinks cooked food, meat and bones are good for compost.', 'Why are meat bones and cooked food kept out of the compost heap?', 'They are the best food for a compost heap', 'They draw rats and flies and smell', 'The child knows meat rots and so thinks it belongs.', 'Ask what comes to a heap with meat scraps in it, and whether the school garden needs those visitors.', 'Meat, bones and oily leftovers draw rats and flies. Peelings, leaves, grass and dung are better.'),
  M('COMPOST_MATERIALS', 'M_AG4_CM_FERT', 'Calls shop fertiliser a compost material.', 'Which of these is made by rotting plant remains and dung?', 'Fertiliser bought from the shop', 'Compost manure', 'The child links manure, fertiliser and compost as one thing.', 'Show a bag of fertiliser and a handful of compost. Ask where each one comes from.', 'Compost is made at home by rotting plant remains and dung. Fertiliser from the shop is made in a factory. They are not the same.'),
  M('COMPOST_MAKING', 'M_AG4_CK_ONE', 'Heaps one kind of material only (all dry sticks or all wet peelings).', 'What makes the best compost heap?', 'Dry and fresh materials mixed in layers', 'Only wet peelings pressed into one heap', 'The child thinks more of one good thing is better.', 'Make two small heaps, one with one material and one with a mix. Compare them after a month.', 'A mix of dry and fresh material in layers rots best. Dry material lets in air and fresh material gives moisture and food for the rotting.'),
  M('COMPOST_MAKING', 'M_AG4_CK_DRY', 'Leaves the heap dry and open, or soaks it with water.', 'What does a compost heap need while it rots?', 'To be kept dry and open to the sun', 'To be kept damp and covered', 'The child thinks rotting happens by itself.', 'Compare a damp covered heap and a dry open heap after a month. Then flood one and smell it.', 'A heap rots best when it is damp, not soaking, and covered. Too dry and it stops rotting. Too wet and it goes smelly.'),
  M('COMPOST_MAKING', 'M_AG4_CK_EARLY', 'Uses the compost before it has rotted.', 'When is compost ready to put on the garden?', 'After one day, when the heap is made', 'When it is dark, crumbly and smells like soil', 'The child thinks compost is ready as soon as it is made.', 'Open a young heap and an old heap side by side. Ask which still looks like peelings.', 'Waste needs weeks to rot. Compost is ready when it is dark, crumbly and smells like soil.'),
  M('DRIP_MEANING', 'M_AG4_DM_FAST', 'Thinks drip irrigation pours water out quickly like a hosepipe.', 'How does drip irrigation give water to a plant?', 'It pours a lot of water out very fast', 'It gives water slowly, drop by drop', 'The child thinks of a tap or hosepipe, not of a drip.', 'Pierce a bottle with a pin hole and watch it. Ask how fast the water comes out.', 'Drip irrigation gives water slowly, drop by drop, so the soil can soak it up.'),
  M('DRIP_MEANING', 'M_AG4_DM_LEAVES', 'Thinks the drip falls on the leaves of the plant.', 'Where does the water from a drip system go?', 'Onto the leaves of the plant', 'Into the soil at the roots', 'The child thinks of rain falling on the plant.', 'Ask which part of the plant takes up water. Look at where a real drip tube ends.', 'The roots take up water, so the drip goes into the soil beside the roots.'),
  M('DRIP_MEANING', 'M_AG4_DM_WASTE', 'Thinks drip irrigation uses more water than a watering can.', 'Why does drip irrigation save water?', 'It uses more water so the plant grows faster', 'Little water is lost and it goes to the roots', 'The child thinks slow means more.', 'Water one bed with a bucket and one by drip. Measure the water used.', 'Drip irrigation puts a small amount of water only where it is needed, so little is wasted.'),
  M('DRIP_SETUP', 'M_AG4_DS_LOW', 'Puts the water container lower than the plants.', 'Where should the water container of a simple drip system be put?', 'Lower than the bed, on the ground', 'Higher than the bed, on a stand', 'The child does not think about water running downhill.', 'Raise and lower a bottle with a hole above a bed. Watch when the water flows.', 'Water runs downhill. The container must stand higher than the bed so the water drips out.'),
  M('DRIP_SETUP', 'M_AG4_DS_BIGHOLE', 'Makes a big hole so the water comes out faster.', 'How big should the hole in a drip bottle be?', 'Big, so all the water comes out at once', 'Tiny, so the water comes out drop by drop', 'The child thinks speed helps the plant.', 'Make one tiny hole and one large hole in two bottles. Watch which waters a whole week.', 'A big hole empties the bottle at once and floods the plant. A tiny hole keeps the drip going for hours.'),
  M('DRIP_SETUP', 'M_AG4_DS_FAR', 'Puts the drip far from the plant roots.', 'Where should the end of the drip tube be placed?', 'Far from the plant, in the middle of the path', 'Next to the plant roots', 'The child does not link the drip to where the roots take water.', 'Dig up a small plant and show how close its roots are to the stem.', 'The water must fall where the roots are, so the drip end is placed next to the plant.'),
  M('FUEL_TYPES', 'M_AG4_FT_PETROL', 'Thinks petrol or diesel is used as a cooking fuel at home.', 'Which of these is a fuel used for cooking at home?', 'Petrol', 'Cooking gas', 'The child knows petrol is a fuel and does not know it is for engines.', 'Ask what burns in a jiko, a gas cooker and a car. Talk about why petrol is dangerous indoors.', 'Petrol and diesel are fuels for engines. They are not used to cook at home because they catch fire too easily.'),
  M('FUEL_TYPES', 'M_AG4_FT_ONE', 'Thinks firewood is the only fuel at home.', 'Which list names only fuels used at home?', 'Firewood, charcoal, paraffin and gas', 'Firewood only, every home uses the same', 'The child sees only the fuel used in their own home.', 'Ask each learner which fuels their home uses and make one class list.', 'Homes use many fuels: firewood, charcoal, paraffin, cooking gas, biogas, electricity and solar.'),
  M('FUEL_TYPES', 'M_AG4_FT_STATE', 'Mixes up solid, liquid and gas fuels.', 'Which of these is a liquid fuel?', 'Charcoal', 'Paraffin', 'The child links fuel names to the fire, not to the form of the fuel.', 'Pour paraffin, hold charcoal and ask how each can be carried and stored.', 'Charcoal and firewood are solids, paraffin is a liquid, and cooking gas and biogas are gases.'),
  M('FUEL_SAVING', 'M_AG4_FS_OPENLID', 'Cooks with the lid off the pot.', 'Which habit saves fuel when boiling beans?', 'Cooking with the lid off so you can watch', 'Cooking with a lid on the pot', 'The child wants to watch the food and does not think the heat escapes.', 'Boil two pots of water, one with a lid and one without, and time them.', 'A lid keeps the heat in so the food cooks faster and uses less fuel.'),
  M('FUEL_SAVING', 'M_AG4_FS_BIG', 'Thinks a big flame cooks food faster and so is better.', 'The pot is boiling. What should the cook do to save fuel?', 'Add more wood so the flame is big', 'Make the fire small to keep it simmering', 'The child thinks more fire means more cooking.', 'Ask whether the water gets hotter than boiling when the flame is bigger.', 'Once water boils it does not get hotter. A big flame only wastes fuel.'),
  M('FUEL_SAVING', 'M_AG4_FS_WET', 'Thinks wet firewood is as good as dry firewood.', 'Which firewood saves the most fuel?', 'Wet, freshly cut wood', 'Dry wood', 'The child thinks all wood burns the same.', 'Try to light a dry stick and a wet one and compare smoke and heat.', 'Wet wood makes smoke and gives little heat because the fire must first dry it. Dry wood burns well.'),
  M('SMALL_PESTS', 'M_AG4_SP_BIG', 'Thinks only big animals harm crops.', 'Which of these small animals can harm a maize field?', 'None, only big animals harm crops', 'Birds, rats and squirrels', 'The child thinks of elephants and baboons in the news.', 'Walk the school plot and look for signs: pecked grain, tunnels, gnawed cobs.', 'Small animals such as birds, rats and squirrels also harm crops, because there are many of them.'),
  M('SMALL_PESTS', 'M_AG4_SP_BEE', 'Thinks bees and butterflies harm crops.', 'Which small animal does NOT harm the crop?', 'A rat in the maize', 'A bee on the bean flower', 'The child thinks every small animal on a crop is a pest.', 'Watch bees on a flowering crop. Ask what happens to the flower afterwards.', 'Bees and butterflies carry pollen between flowers and help crops to give seed and fruit.'),
  M('SMALL_PESTS', 'M_AG4_SP_MATCH', 'Links an animal to the wrong damage (moles eating leaves, birds digging roots).', 'Which animal digs up roots and tubers under the ground?', 'A weaver bird', 'A mole', 'The child knows the animal is a pest but not what it eats.', 'Match pictures of the animals to pictures of the damage.', 'Birds peck grain, rats gnaw grain and cobs, and moles tunnel under the ground and eat roots and tubers.'),
  M('SCARECROW_MAKE', 'M_AG4_SC_FIXED', 'Thinks a scarecrow can stay in one place all season.', 'Why is a scarecrow moved from place to place?', 'It does not need to be moved at all', 'Animals get used to it if it never moves', 'The child thinks it scares by being there.', 'Ask what a bird does after a week of seeing the same scarecrow that never moves.', 'Birds soon learn that a still scarecrow is harmless. Moving it and changing its clothes keeps them afraid.'),
  M('SCARECROW_MAKE', 'M_AG4_SC_KILL', 'Thinks a scarecrow, or poison and traps, should kill the animals.', 'What is a scarecrow made to do?', 'Kill the animals that come near', 'Scare the animals away without hurting them', 'The child thinks protecting crops means killing pests.', 'Ask who also visits the plot, such as bees, and what poison would do to them.', 'A scarecrow only scares animals away. Poison and traps can harm many other animals as well.'),
  M('SCARECROW_MAKE', 'M_AG4_SC_HIDDEN', 'Hides the scarecrow at the edge of the crop.', 'Where is the best place to stand a scarecrow?', 'Hidden in the bush at the edge', 'In the middle of the crop, where it can be seen', 'The child thinks it should be a surprise.', 'Stand a scarecrow at the edge and in the middle and ask which one the bird can see from the sky.', 'Birds must see the scarecrow from far. Put it high in the middle of the crop.'),
  M('TINY_SEED_CROPS', 'M_AG4_TS_BIGSEED', 'Thinks maize and beans have tiny seeds.', 'Which crop has a large seed, not a tiny one?', 'Carrot', 'Maize', 'The child links "seed" to any crop sown from seed.', 'Put a maize seed, a bean and a carrot seed in the hand and compare them.', 'Maize, beans and peas have large seeds. Carrot, spinach and coriander have tiny seeds.'),
  M('TINY_SEED_CROPS', 'M_AG4_TS_NURSERY', 'Thinks cabbage and tomato are sown straight in the plot like carrot.', 'Which crop is usually started in a nursery and moved later?', 'Carrot', 'Cabbage', 'The child thinks all tiny seeds are treated the same.', 'Ask a farmer how he starts carrots and how he starts tomatoes.', 'Carrots do not like being moved, so they are sown where they will grow. Cabbage and tomato are started in a nursery.'),
  M('TINY_SEED_CROPS', 'M_AG4_TS_CUTTING', 'Thinks crops grown from cuttings, such as sweet potato vines, are sown from tiny seeds.', 'How is a sweet potato crop usually planted?', 'By sowing tiny seeds', 'By planting pieces of vine', 'The child thinks every crop starts from seed.', 'Show a sweet potato vine cutting next to a packet of carrot seed.', 'Sweet potato is planted from vine cuttings, not seeds.'),
  M('SEEDBED_SOWING', 'M_AG4_SB_COARSE', 'Thinks lumps and stones in the seedbed do not matter.', 'How should the soil of a seedbed for tiny seeds be?', 'Rough, with lumps and stones', 'Fine, like flour', 'The child thinks seeds will find their way.', 'Sow tiny seeds in a lumpy bed and a fine bed and compare how many come up.', 'Tiny seeds need fine soil to touch. Lumps and stones stop them from coming up.'),
  M('SEEDBED_SOWING', 'M_AG4_SB_DEEP', 'Sows tiny seeds deep.', 'How deep are tiny seeds sown?', 'Deep, about as deep as a hand', 'Very shallow, and covered lightly', 'The child thinks deep soil protects the seeds.', 'Sow seeds at two depths and see which come up. A tiny seed has little food to push up.', 'Tiny seeds have little stored food and cannot push up from deep soil. Sow them very shallow.'),
  M('SEEDBED_SOWING', 'M_AG4_SB_THICK', 'Sows thickly and never thins the seedlings.', 'What should be done when carrot seedlings come up crowded?', 'Leave them all, more plants give more carrots', 'Thin them so each has room', 'The child thinks more plants means more crop.', 'Grow one thick row and one thinned row. Compare the carrots at harvest.', 'Crowded plants fight for light, water and food. Thin them so each can grow big.'),
  M('FRUIT_TYPES', 'M_AG4_FY_ANYWHERE', 'Thinks any fruit grows well anywhere.', 'Which fruit does best at the hot coast?', 'Apple', 'Mango', 'The child sees all fruits for sale in the market and does not know where they come from.', 'Ask which fruits grow near the school and which come from far.', 'Mango likes the warm coast. Apples need the cool highlands.'),
  M('FRUIT_TYPES', 'M_AG4_FY_TREE', 'Thinks fruits grow only on tall trees.', 'Which of these gives a fruit but is not a tall tree?', 'None, all fruits come from tall trees', 'Banana and pawpaw plants', 'The child pictures a mango tree for every fruit.', 'Look at a banana plant and a passion fruit vine and ask where the fruit hangs.', 'Fruits grow on trees, bushes, vines and plants like banana and pawpaw.'),
  M('FRUIT_TYPES', 'M_AG4_FY_ROOT', 'Calls a root crop a fruit.', 'Which of these is NOT a fruit crop?', 'Cassava', 'Guava', 'The child thinks all sweet or eaten crops are fruits.', 'Dig up a cassava plant and ask which part we eat.', 'Cassava is a root crop. Fruit crops give fruits that grow from flowers, like guava.'),
  M('FRUIT_GROWING', 'M_AG4_FG_DEEP', 'Plants the seedling deeper than it grew, or buries the stem.', 'How deep should a fruit seedling be planted?', 'Deep, with the stem buried', 'At the same depth it grew in the bag', 'The child thinks deeper is safer.', 'Show the soil mark on the stem of a seedling.', 'Plant it at the depth it grew. A buried stem can rot.'),
  M('FRUIT_GROWING', 'M_AG4_FG_NOMANURE', 'Plants in plain hard soil with no manure.', 'What is mixed with the topsoil in the planting hole?', 'Stones and sand only', 'Manure or compost', 'The child thinks a hole is only a place to stand the plant.', 'Plant two seedlings, one with manure and one without, and compare after a month.', 'Manure in the hole feeds the young plant and loosens the soil so the roots can spread.'),
  M('FRUIT_GROWING', 'M_AG4_FG_CROWD', 'Plants seedlings close together to save space.', 'How far apart should mango seedlings be planted?', 'As close as possible to save space', 'Far enough apart for each tree to grow wide', 'The child thinks of the small seedling and not the big tree.', 'Show how wide a mature mango tree is.', 'A fruit tree grows big. It needs room for its roots and branches.'),
  M('FRUIT_GROWING', 'M_AG4_FG_DRYSTOP', 'Stops watering after the first day.', 'How is a young fruit seedling looked after in dry weather?', 'Water once on the day it is planted, then stop', 'Water it regularly and keep a mulch around it', 'The child thinks planting finishes the job.', 'Ask what happens to a seedling that dries out for a week.', 'A young seedling has short roots and dries quickly. It needs regular water and a mulch.'),
  M('ANIMAL_TYPES', 'M_AG4_AT_WILD', 'Calls a wild animal domestic because it is seen near homes.', 'Which of these is a domestic animal?', 'A zebra', 'A goat', 'The child thinks any animal near people is domestic.', 'Ask who feeds, houses and looks after each animal.', 'Domestic animals are kept and cared for by people. Zebras are wild.'),
  M('ANIMAL_TYPES', 'M_AG4_AT_FOUR', 'Thinks only four-legged animals are domestic animals (leaves out chickens and bees).', 'Which of these is a domestic animal kept for eggs?', 'None, birds are not domestic animals', 'A chicken', 'The child pictures a cow or a goat as an animal.', 'Ask which birds the community keeps at home.', 'Chickens, ducks and turkeys are domestic animals called poultry. Bees can be kept too.'),
  M('ANIMAL_TYPES', 'M_AG4_AT_GROUP', 'Puts an animal in the wrong group (a goat in poultry, a duck in livestock).', 'Which of these is poultry?', 'A goat', 'A duck', 'The child sorts by size and noise.', 'Ask which animals have feathers and lay eggs.', 'Poultry are birds kept for eggs and meat, like chickens, ducks and turkeys. Goats are livestock.'),
  M('ANIMAL_USES', 'M_AG4_AU_MIX', 'Gives an animal the wrong product (eggs from cows, wool from goats).', 'Which animal gives us wool?', 'A goat', 'A sheep', 'The child knows the product but not which animal gives it.', 'Show wool, milk, eggs and honey and ask where each comes from.', 'Sheep give wool. Goats give milk and meat. Chickens give eggs and cattle give milk.'),
  M('ANIMAL_USES', 'M_AG4_AU_ONE', 'Thinks an animal gives only one thing.', 'Which animal gives us milk, meat and hides?', 'None, an animal gives only one thing', 'A cow', 'The child learns one animal with one use.', 'Make a list of everything one cow gives the family.', 'Many animals give more than one thing. A cow gives milk, meat and hides, and it can plough too.'),
  M('ANIMAL_USES', 'M_AG4_AU_WORK', 'Thinks any animal can pull a plough or carry a load.', 'Which animal is used to carry loads?', 'A hen', 'A donkey', 'The child thinks all animals can work.', 'Ask which animals in the village pull carts and which do not.', 'Donkeys, camels and oxen are strong enough to carry or pull. Hens and rabbits are too small.'),
  M('MEAL_IMPORTANCE', 'M_AG4_MI_FILL', 'Thinks a meal is good if it fills the stomach.', 'What makes a meal balanced?', 'It is big enough to fill the stomach', 'It has foods from all the groups', 'The child links good food with being full.', 'Compare a large plate of ugali alone with a smaller plate of ugali, beans and greens.', 'A full stomach is not the same as a balanced meal. A balanced meal has foods from every group.'),
  M('MEAL_IMPORTANCE', 'M_AG4_MI_ONE', 'Thinks one food, such as ugali, gives the body everything.', 'Why can a child not live on ugali alone?', 'Ugali gives everything the body needs', 'It does not give all the things the body needs', 'The child eats one staple most days.', 'Ask what happens to a child who eats only one food for months.', 'No single food has everything. The body needs a mix of foods.'),
  M('MEAL_IMPORTANCE', 'M_AG4_MI_COST', 'Thinks a balanced meal needs expensive food.', 'Which family can eat a balanced meal?', 'Only a rich family that can buy meat', 'Any family that mixes foods from all groups', 'The child links balance with money.', 'Make a cheap balanced meal with ugali, ndengu and managu.', 'Beans, greens and a staple make a balanced meal that costs little.'),
  M('GROUPS_SORT', 'M_AG4_GS_UGALI', 'Puts ugali or rice with the body-building foods because they fill you.', 'Ugali gives mainly what?', 'Body building', 'Energy', 'The child thinks filling food builds the body.', 'Ask what a runner eats before a race and why.', 'Ugali, rice and chapati are energy-giving foods. Body-building foods are beans, meat, fish and eggs.'),
  M('GROUPS_SORT', 'M_AG4_GS_MEAT', 'Puts meat, eggs and beans with the energy foods.', 'Eggs, fish and beans help the body to do what mainly?', 'Give energy', 'Build and repair the body', 'The child thinks all food that fills gives energy.', 'Ask which foods a growing child or someone with a wound needs.', 'Eggs, fish, meat and beans are body-building foods. They help the body grow and mend.'),
  M('GROUPS_SORT', 'M_AG4_GS_FRUIT', 'Puts fruits and vegetables with the body-building foods.', 'Sukuma wiki and mangoes are which kind of food?', 'Body-building', 'Protective', 'The child thinks anything that is good for you builds the body.', 'Ask what protective means and which colours protect the body.', 'Vegetables and fruits are protective foods. They help the body fight illness.'),
  M('MEAL_PICK', 'M_AG4_MP_ONE', 'Picks a plate with only one group, such as ugali, rice and chapati.', 'Which plate is a balanced meal?', 'Ugali, rice and chapati', 'Ugali, beans and sukuma wiki', 'The child counts the number of foods, not the groups.', 'Sort each food on the plate into a group. Count the groups.', 'Ugali, rice and chapati are all energy foods. A balanced meal has one from each group.'),
  M('MEAL_PICK', 'M_AG4_MP_NOVEG', 'Leaves out vegetables or fruit and calls the meal balanced.', 'A child eats ugali and fish. What is missing?', 'Nothing is missing', 'A protective food such as sukuma wiki', 'The child does not count vegetables as part of the meal.', 'Ask which group each food is in and which group is empty.', 'Ugali is energy and fish is body-building. Add vegetables or fruit for the protective group.'),
  M('MEAL_PICK', 'M_AG4_MP_SWEET', 'Thinks soda, sweets or biscuits complete a meal.', 'Which one makes a meal more balanced?', 'A bottle of soda', 'A fruit', 'The child thinks anything extra is good.', 'Look at what a soda gives: sugar and no body-building or protective foods.', 'Soda and sweets give sugar only. A fruit or vegetable gives protective food.'),
  M('COOKING_METHODS', 'M_AG4_CMT_STEAM', 'Thinks steaming means the food sits in the water.', 'In steaming, where is the food?', 'Inside the boiling water', 'Above the water, cooked by the steam', 'The child mixes boiling and steaming.', 'Show a steamer with the food on a rack above the water.', 'In steaming the food stays above the water and the steam cooks it.'),
  M('COOKING_METHODS', 'M_AG4_CMT_FRY', 'Thinks shallow frying uses no oil, or uses a deep pot of oil.', 'What is used in shallow frying?', 'A pot full of oil to cover the food', 'A little oil in a pan', 'The child mixes shallow and deep frying.', 'Show a frying pan with a spoonful of oil beside a pot full of oil.', 'Shallow frying uses a little oil in a pan. Chapati and eggs are shallow fried.'),
  M('COOKING_METHODS', 'M_AG4_CMT_ROAST', 'Thinks roasting is cooking in water.', 'How is a maize cob roasted?', 'In a pot of boiling water', 'Over a fire or in an oven, with dry heat', 'The child links all cooking with a pot of water.', 'Roast a cob over a jiko and compare it with a boiled cob.', 'Roasting cooks food by dry heat over a fire or in an oven. Boiling uses water.'),
  M('COOKING_SUIT', 'M_AG4_CS_FRYALL', 'Thinks every food is best fried.', 'Which method suits dry beans best?', 'Shallow frying', 'Boiling', 'The child likes fried food and thinks frying cooks everything.', 'Try to fry dry beans and ask why they stay hard.', 'Dry beans are hard and need a long time in boiling water. Frying would burn them outside and leave them hard inside.'),
  M('COOKING_SUIT', 'M_AG4_CS_OVER', 'Cooks green vegetables for a long time.', 'How long should sukuma wiki be cooked?', 'For a very long time until it is soft and brown', 'For a short time, until it is just soft and still green', 'The child thinks longer cooking makes food safer.', 'Cook greens for 3 minutes and for 30 minutes and compare colour and taste.', 'Overcooked greens lose their colour and goodness. Cook them only until soft.'),
  M('COOKING_SUIT', 'M_AG4_CS_SHORT', 'Thinks hard foods such as beans cook as fast as soft foods.', 'Which food needs the longest time to cook?', 'Spinach', 'Dry beans', 'The child does not tell hard foods from soft foods.', 'Put beans and spinach in two pots and see which is soft first.', 'Hard foods like dry beans need hours. Soft foods like spinach need minutes.'),
  M('COOKING_SAFE', 'M_AG4_CF_HANDLE', 'Leaves the pot handle sticking out over the edge of the stove.', 'How should the handle of a pot on the stove be turned?', 'Sticking out, so it is easy to reach', 'Turned inwards, away from the edge', 'The child thinks of reaching, not of knocking.', 'Ask what happens when a child passes and brushes the handle.', 'A handle that sticks out can be knocked and the hot food spills. Turn it inwards.'),
  M('COOKING_SAFE', 'M_AG4_CF_WATERFIRE', 'Throws water on an oil fire.', 'The oil in a pan catches fire. What should be done?', 'Pour water on it', 'Cover it with a lid and call a grown-up', 'The child thinks water puts out every fire.', 'Talk about why water makes burning oil splash and spread.', 'Water spreads burning oil. A lid shuts out the air and puts the fire out.'),
  M('COOKING_SAFE', 'M_AG4_CF_LEAVE', 'Leaves a pot or a fire alone while cooking.', 'The pot is on the fire. What should the cook do?', 'Go out and play, it will be fine', 'Stay near and watch the pot', 'The child thinks cooking needs no watching.', 'Ask what can happen to a pot that boils dry or a fire that spreads.', 'A cooking fire must never be left alone. A pot can boil dry or burn and the fire can spread.'),
  M('HYGIENE_PRACTICES', 'M_AG4_HP_PERFUME', 'Thinks perfume or oil takes the place of washing.', 'Which keeps the body clean?', 'Putting on perfume', 'Bathing with soap and water', 'The child thinks smelling nice means clean.', 'Ask whether perfume washes dirt and germs off the skin.', 'Perfume only covers a smell. Soap and water take dirt and germs off the body.'),
  M('HYGIENE_PRACTICES', 'M_AG4_HP_RARE', 'Thinks bathing or brushing teeth once a week is enough.', 'How often should teeth be brushed?', 'Once a week', 'In the morning and at night', 'The child thinks cleaning is only for special days.', 'Look at how quickly a smooth tooth feels rough again.', 'Teeth should be brushed in the morning and at night. The body should be bathed every day.'),
  M('HYGIENE_PRACTICES', 'M_AG4_HP_HANDS', 'Thinks hands that look clean are clean.', 'Why must hands that look clean still be washed before eating?', 'Hands that look clean cannot have germs', 'Germs are too small to see', 'The child trusts the eye.', 'Rub clean-looking hands in glitter or powder and see how it spreads.', 'Germs are too small to see. Wash hands with soap before eating even if they look clean.'),
  M('HAND_WASHING', 'M_AG4_HW_NOSOAP', 'Thinks a rinse in water is enough.', 'What do we use to wash hands properly?', 'Water only', 'Soap and clean water', 'The child thinks water removes everything.', 'Wash greasy hands with water only and then with soap.', 'Soap lifts dirt and germs off the skin. Water alone does not.'),
  M('HAND_WASHING', 'M_AG4_HW_QUICK', 'Dips the hands in and takes them out at once.', 'How long should hands be rubbed with soap?', 'One second, a quick dip is enough', 'As long as it takes to sing a short song', 'The child thinks speed is cleanliness.', 'Count while rubbing with soap and talk about how long it takes to reach under the nails.', 'Rub the soap on all parts of the hands for about as long as a short song, then rinse.'),
  M('HAND_WASHING', 'M_AG4_HW_BEFORE', 'Washes only after eating and not before.', 'When must hands be washed?', 'After eating only', 'Before eating and after using the toilet', 'The child washes to remove food, not germs.', 'Ask what is on hands before a meal after playing outside.', 'Wash before eating or cooking, and after the toilet, playing outside or touching animals.'),
  M('CLEANING_METHODS', 'M_AG4_CLM_MIX', 'Mixes up the ways of cleaning (sweeping a wet floor, mopping dust).', 'Which method removes dry dirt from a floor?', 'Mopping', 'Sweeping', 'The child thinks every floor job is mopping.', 'Try to sweep a muddy floor and mop a dusty one.', 'Sweeping removes dry dirt with a broom. Mopping cleans with a wet cloth and water.'),
  M('CLEANING_METHODS', 'M_AG4_CLM_DUST', 'Thinks dusting means sweeping the yard.', 'What is dusting?', 'Sweeping the compound outside', 'Wiping dust off shelves and furniture', 'The child links dust with the ground.', 'Wipe a table with a cloth and look at the dust on it.', 'Dusting wipes dust from shelves, tables and other furniture with a cloth.'),
  M('CLEANING_METHODS', 'M_AG4_CLM_RUBBISH', 'Throws rubbish anywhere or burns plastic.', 'Where should rubbish from the house go?', 'Anywhere outside, the wind will take it', 'Into a bin or a rubbish pit', 'The child thinks outside is for dirt.', 'Walk round the school and look at where rubbish piles up and what it attracts.', 'Rubbish goes into a bin or a pit. Loose rubbish attracts flies and rats and spreads sickness.'),
  M('CLEANING_ORDER', 'M_AG4_CO_FLOOR', 'Sweeps the floor first and dusts the shelves after.', 'Which job comes first when cleaning a room?', 'Sweeping the floor', 'Dusting the shelves', 'The child cleans from the dirtiest part.', 'Dust a shelf over a swept floor and look at the floor again.', 'Dust falls to the floor, so dust the shelves first and sweep the floor after.'),
  M('CLEANING_ORDER', 'M_AG4_CO_MOP', 'Mops before sweeping.', 'What comes first, sweeping or mopping?', 'Mopping, then sweeping', 'Sweeping, then mopping', 'The child thinks water does all the work.', 'Mop a dusty floor and see the mud it makes.', 'Sweep first to lift the dry dirt. Mop last so the floor comes out clean.'),
  M('CLEANING_ORDER', 'M_AG4_CO_GREASY', 'Washes the greasy sufuria first in the same water.', 'Which should be washed first?', 'The greasy sufuria', 'The cups and plates', 'The child washes the dirtiest first.', 'Wash a cup after a greasy pot in the same water and feel it.', 'Wash the cleanest things first (cups, plates) and the greasy pots last, so the water stays clean longer.'),
  M('PPE_ITEMS', 'M_AG4_PI_MATCH', 'Matches the wrong protective item to the job (gloves for the eyes, a mask for the feet).', 'Which item protects the eyes?', 'Gloves', 'Goggles', 'The child knows the items but not the body part each protects.', 'Hold each item up and say which body part it covers.', 'Goggles protect the eyes, gloves protect the hands, gumboots protect the feet and a mask protects the nose and mouth.'),
  M('PPE_ITEMS', 'M_AG4_PI_FASHION', 'Thinks protective clothing is for looks.', 'Why does a farmer wear a face mask when spraying?', 'To look smart', 'To keep the spray out of the nose and mouth', 'The child has seen the clothing but not its job.', 'Ask what would happen to a farmer who breathes in the spray.', 'Protective clothing keeps dust, germs and chemicals off the body. It is not for looks.'),
  M('PPE_ITEMS', 'M_AG4_PI_SANDALS', 'Thinks sandals protect the feet on the farm.', 'Which footwear protects a farmer in wet muddy ground?', 'Open sandals', 'Gumboots', 'The child thinks any shoe will do.', 'Ask what can cut or bite a bare foot in a shamba.', 'Gumboots cover the whole foot and keep out water, mud, thorns and snakes.'),
  M('PPE_CARE', 'M_AG4_PC_DIRTY', 'Puts protective clothing away dirty.', 'What is done with a muddy apron after work?', 'Hang it away as it is', 'Wash it with soap and water', 'The child thinks it will clean itself.', 'Smell a stored muddy apron after a week.', 'Dirty protective clothing keeps germs and chemicals. Wash it after use.'),
  M('PPE_CARE', 'M_AG4_PC_WET', 'Stores gloves or boots while wet.', 'How should washed gloves be stored?', 'Packed away while still wet', 'Dried fully, then kept in a clean dry place', 'The child is in a hurry to put things away.', 'Pack away a damp cloth in a bag and smell it a week later.', 'Wet items grow mould and smell. Dry them well before storing.'),
  M('PPE_CARE', 'M_AG4_PC_SHARE', 'Shares a dirty mask or gloves with others.', 'Two children want to use the same dirty gloves. What is best?', 'Share them, gloves are gloves', 'Wash them first, or each use a clean pair', 'The child thinks sharing is always kind.', 'Ask how germs and chemicals move from one hand to another.', 'Dirty protective clothing can pass germs from one child to another. Clean it first.'),
  M('TACK_TYPES', 'M_AG4_TT_PERM', 'Thinks tacking is the final stitching and stays in the cloth.', 'What is tacking used for?', 'To join the cloth for good', 'To hold the cloth together for a short time', 'The child sees a stitch and thinks it is the finished seam.', 'Tack two pieces and sew them, then pull out the tacking.', 'Tacking is temporary. It holds the cloth in place until the final stitching is done.'),
  M('TACK_TYPES', 'M_AG4_TT_NAME', 'Mixes up even, uneven and diagonal tacking.', 'Which tacking has long stitches on top and short stitches underneath?', 'Even tacking', 'Uneven tacking', 'The child does not look at the length of the stitches.', 'Make each tacking on a scrap and compare the top and the back.', 'Even tacking has equal stitches. Uneven tacking has long top stitches and short ones underneath. Diagonal tacking slants.'),
  M('TACK_TYPES', 'M_AG4_TT_SMALL', 'Thinks tacking stitches are tiny and strong.', 'What are tacking stitches like?', 'Tiny and tight', 'Long and loose', 'The child thinks all stitches are made to last.', 'Pull out a tacking stitch and then a back stitch and compare.', 'Tacking stitches are long and loose so they are quick to make and easy to take out.'),
  M('TACK_USE', 'M_AG4_TU_KEEP', 'Leaves the tacking in the finished garment.', 'What is done with the tacking when the sewing is finished?', 'It is left in the cloth', 'It is pulled out', 'The child sees it as part of the stitching.', 'Show a garment with tacking left in and ask what it looks like.', 'Tacking is only a guide. Pull it out when the final stitching is done.'),
  M('TACK_USE', 'M_AG4_TU_ORDER', 'Sews the final seam first and tacks after.', 'What comes first, tacking or the final stitching?', 'Final stitching, then tacking', 'Tacking, then final stitching', 'The child does not know tacking is a guide.', 'Sew two slippery pieces without tacking and see them slide.', 'Tack first to hold the cloth, then sew the final stitching beside it.'),
  M('TACK_USE', 'M_AG4_TU_STRONG', 'Tacks with tiny strong stitches in matching thread.', 'How should tacking be sewn?', 'With tiny, strong stitches', 'With long, loose stitches in a thread that shows', 'The child thinks every stitch must be neat and strong.', 'Compare how long it takes to unpick tiny stitches and long stitches.', 'Long loose stitches in a thread that shows are easy to see and to pull out.'),
];
